<?php get_header(); ?><main class="site-main article-shell"><?php while (have_posts()): the_post(); ?><article class="article"><p class="breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">NHK</a> <span>/</span> <?php the_category(', '); ?></p><header class="article-header"><p class="eyebrow"><?php the_category(' · '); ?></p><h1><?php the_title(); ?></h1><p class="standfirst"><?php echo esc_html(nhk_v3_excerpt()); ?></p><div class="article-meta"><?php echo esc_html(get_the_author()); ?> · <?php echo esc_html(get_the_date()); ?><?php if (get_the_modified_time('U') !== get_the_time('U')): ?> · Cập nhật <?php echo esc_html(get_the_modified_date()); ?><?php endif; ?></div></header><?php if (has_post_thumbnail()): ?><figure class="article-featured"><?php the_post_thumbnail('large', ['loading' => 'eager']); ?><?php if (get_the_post_thumbnail_caption()): ?><figcaption><?php echo esc_html(get_the_post_thumbnail_caption()); ?></figcaption><?php endif; ?></figure><?php endif; ?><div class="article-content"><?php the_content(); ?></div></article><?php endwhile; ?></main><?php get_footer(); ?>
